public enum ClientError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidInput(field: String, reason: String
    )
    case DecodeFailure(message: String
    )
    case ProtocolMismatch(expected: UInt32, actual: UInt32?, version: String?
    )
    case TooLarge(actual: UInt64, limit: UInt64
    )
    case CursorExpired
    case StaleConfirmation
    case ClosedClient
    case InternalFailure(code: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

