extension ClientError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientError: FfiConverterRustBuffer {
    typealias SwiftType = ClientError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            field: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .DecodeFailure(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .ProtocolMismatch(
            expected: try FfiConverterUInt32.read(from: &buf), 
            actual: try FfiConverterOptionUInt32.read(from: &buf), 
            version: try FfiConverterOptionString.read(from: &buf)
            )
        case 4: return .TooLarge(
            actual: try FfiConverterUInt64.read(from: &buf), 
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 5: return .CursorExpired
        case 6: return .StaleConfirmation
        case 7: return .ClosedClient
        case 8: return .InternalFailure(
            code: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(field,reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .DecodeFailure(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ProtocolMismatch(expected,actual,version):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(expected, into: &buf)
            FfiConverterOptionUInt32.write(actual, into: &buf)
            FfiConverterOptionString.write(version, into: &buf)
            
        
        case let .TooLarge(actual,limit):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(actual, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)
            
        
        case .CursorExpired:
            writeInt(&buf, Int32(5))
        
        
        case .StaleConfirmation:
            writeInt(&buf, Int32(6))
        
        
        case .ClosedClient:
            writeInt(&buf, Int32(7))
        
        
        case let .InternalFailure(code):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            
        }
    }
}


