    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceClientObserver] = [UniffiVTableCallbackInterfaceClientObserver(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceClientObserver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface ClientObserver: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceClientObserver.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ClientObserver: handle missing in uniffiClone")
            }
        },
        changed: { (
            uniffiHandle: UInt64,
            notice: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
